# SIMULATED extraction for the Module 5 dry run (ground rule 2: simulated
# data live only in sim/, are generated by a visible script and never written
# under data/). Same columns as data/extracted/meta_extraction.csv. All
# numbers are SIMULATION SETTINGS, not published values.
#
# Each configured drug class gets `k` studies against non-users and, for the
# classes in an informative contrast, `k` active-comparator studies. True log
# ratios: anticholinergic +0.25 (the positive control must be recovered);
# every noradrenergic class 0 (a null world, so the dry run also shows what
# "no effect" looks like in every table and figure).

meta_simulate_extraction <- function(cfg, seed, k = 6) {
  set.seed(seed)
  contrast_of <- c(lipophilic_beta_blocker = "lipophilic_vs_hydrophilic_beta_blocker",
                   alpha1_blocker = "alpha1_blocker_vs_tamsulosin",
                   dual_orexin_antagonist = "z_drug_vs_dual_orexin_antagonist",
                   atomoxetine = "atomoxetine_vs_stimulant",
                   dhp_calcium_channel_blocker = "brain_penetrant_vs_nonpenetrant_dhp_ccb")
  rows <- list()
  for (cls in names(cfg$drug_classes)) {
    truth <- if (cls == cfg$positive_control$drug_class) 0.25 else 0
    types <- if (cls %in% names(contrast_of)) c("non_user", "active") else "non_user"
    for (ct in types) for (i in seq_len(k)) {
      se <- stats::runif(1, 0.08, 0.3)
      y <- stats::rnorm(1, truth, se)
      z <- stats::qnorm(0.975)
      est <- exp(y)
      rows[[length(rows) + 1]] <- data.frame(
        study_id = sprintf("SIM_%s_%s_%d", cls, ct, i), drug_class = cls, drug = paste0("sim_", cls),
        comparator_type = ct, comparator = if (ct == "active") "sim_active_comparator" else "non-users",
        contrast = if (ct == "active") contrast_of[[cls]] else "none",
        outcome = "all-cause dementia", effect_measure = "HR",
        estimate = sprintf("%.6f", est), ci_lower = sprintf("%.6f", exp(y - z * se)),
        ci_upper = sprintf("%.6f", exp(y + z * se)), ci_level = "0.95", covariates = "simulated",
        brain_penetrance = if (cls == "anticholinergic") "not_applicable" else sample(c("high", "low"), 1),
        robins_d1 = "not_assessed", robins_d2 = "not_assessed", robins_d3 = "not_assessed",
        robins_d4 = "not_assessed", robins_d5 = "not_assessed", robins_d6 = "not_assessed",
        robins_d7 = "not_assessed", source_id = "SIMULATED", locator = "simulated", quantity = "simulated",
        verbatim = "simulated", verified = "false", machine_rechecked = "false", invert_ratio = "false",
        include = "true", exclusion_reason = "none", stringsAsFactors = FALSE)
    }
  }
  do.call(rbind, rows)
}
